<?php
require __DIR__.'/programaciones-common.php';
$id=prog_id($_GET,'id_plantilla',true);
$row=$id?prog_template($id):['descripcion'=>'','monitor'=>0,'nivel'=>0,'periodicidad'=>0,'num_sesiones'=>12];
$monitors=app_rows("SELECT id_usuario,Nombre,Apellido1,Apellido2 FROM usuarios WHERE tipo_inscripcion=4 OR id_usuario=? ORDER BY Apellido1,Apellido2,Nombre",'i',[(int)$row['monitor']]);
$sessions=[];$groups=[];
if($id){foreach(app_rows('SELECT numero_sesion,COUNT(*) AS actividades FROM agenda_programacion_plantillas_actividades WHERE id_plantilla=? GROUP BY numero_sesion','i',[$id]) as $s)$sessions[(int)$s['numero_sesion']]=(int)$s['actividades'];$groups=app_rows('SELECT v.*,g.dia,g.hora_inicio,g.hora_fin FROM agenda_programacion_grupos_vinculados v LEFT JOIN aulas_grupos g ON g.id_grupo=v.id_grupo WHERE v.id_plantilla=? ORDER BY g.dia,g.hora_inicio','i',[$id]);}
prog_header($id?($row['descripcion']?:'Editar programación'):'Nueva programación','Define la programación y prepara sus sesiones. Los cambios se guardan al pulsar Guardar.');
if(app_value($_GET,'done')==='saved'){?><p class="prog-notice" role="status">Cambios guardados.</p><?php }?>
<a class="prog-back" href="gestion_programaciones.php">← Volver a programaciones</a>
<div class="prog-editor-layout"><section class="prog-panel prog-details"><h2>Datos de la programación</h2><form method="post" action="guarda_plantilla.php" id="prog-template-form">
<input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="retorno" value="1">
<label>Nombre de la programación<input type="text" name="descripcion" required maxlength="255" value="<?=app_escape($row['descripcion'])?>" placeholder="Por ejemplo, Nivel 1 · Primer trimestre"></label>
<label>Monitor<select name="monitor"><option value="0">Sin monitor asignado</option><?php foreach($monitors as $monitor){?><option value="<?=(int)$monitor['id_usuario']?>" <?=(int)$monitor['id_usuario']===(int)$row['monitor']?'selected':''?>><?=app_escape(trim($monitor['Nombre'].' '.$monitor['Apellido1'].' '.$monitor['Apellido2']))?></option><?php }?></select></label>
<div class="prog-form-grid"><label>Nivel<select name="nivel"><?php for($i=0;$i<4;$i++){?><option value="<?=$i?>" <?=$i===(int)$row['nivel']?'selected':''?>><?=app_escape(prog_level($i))?></option><?php }?></select></label><label>Repetición<select name="periodicidad" id="prog-periodicity"><option value="0" <?=(int)$row['periodicidad']===0?'selected':''?>>Semanal</option><option value="1" <?=(int)$row['periodicidad']===1?'selected':''?>>Mensual</option></select></label></div>
<label>Número de sesiones<input type="number" name="num_sesiones" id="prog-session-count" min="1" max="<?=(int)$row['periodicidad']===1?12:52?>" required value="<?=(int)$row['num_sesiones']?>"></label><p class="prog-muted" id="prog-session-help">Hasta 52 sesiones semanales o 12 mensuales. Las sesiones que ya tienen actividades se conservan.</p><button class="prog-button" type="submit">Guardar programación</button></form></section>
<section class="prog-panel prog-sessions"><div class="prog-section-title"><div><h2>Sesiones</h2><p class="prog-muted">Abre una sesión para elegir y ordenar sus actividades.</p></div><span class="prog-badge"><?=count(array_filter($sessions,fn($key)=>$key<=(int)$row['num_sesiones'],ARRAY_FILTER_USE_KEY))?> preparadas</span></div>
<?php if(!$id){?><div class="prog-empty"><h3>Empieza por guardar la programación</h3><p>Después podrás preparar las actividades de cada sesión.</p></div><?php }else{?><div class="prog-session-grid"><?php for($session=1;$session<=(int)$row['num_sesiones'];$session++){$count=$sessions[$session]??0;?><a href="editar_plantillas.php?id_plantilla=<?=$id?>&amp;sesion_editada=<?=$session?>" class="prog-session <?=$count?'ready':'pending'?>"><span>Sesión <?=$session?></span><strong><?=$count?> <?=$count===1?'actividad':'actividades'?></strong><small><?=$count?'Preparada':'Por preparar'?></small></a><?php }?></div><?php }?></section></div>
<?php if($id){?><section class="prog-panel prog-assignments"><div class="prog-section-title"><div><h2>Grupos asignados</h2><p class="prog-muted">La programación comienza en la fecha indicada para cada grupo.</p></div><a class="prog-button secondary" href="vincular_plantilla.php?id_plantilla=<?=$id?>">Asignar a un grupo</a></div>
<?php if(!$groups){?><div class="prog-empty"><p>Esta programación todavía no tiene grupos asignados.</p></div><?php }else{?><div class="prog-table-wrap"><table class="prog-table"><thead><tr><th>Horario</th><th>Subgrupo</th><th>Comienza</th><th>Acción</th></tr></thead><tbody><?php $days=[0=>'Domingo',1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'];foreach($groups as $group){?><tr><td><?=app_escape(isset($group['dia'])?($days[(int)$group['dia']]??'Día sin definir'):'Grupo no disponible')?> <span class="prog-muted"><?=app_escape(substr((string)$group['hora_inicio'],0,5).' – '.substr((string)$group['hora_fin'],0,5))?></span></td><td><?=(int)$group['id_subgrupo']?></td><td><?=app_escape($group['fecha_inicio']&&$group['fecha_inicio']!=='0000-00-00'?date('d/m/Y',strtotime($group['fecha_inicio'])):'Sin fecha')?></td><td><form method="post" action="quitar_vinculacion.php" data-confirm="¿Desvincular esta programación del grupo? Sus actividades se conservarán en la biblioteca."><input type="hidden" name="id_plantilla" value="<?=$id?>"><input type="hidden" name="id_vinculacion" value="<?=(int)$group['id_vinculacion']?>"><button class="prog-button small secondary" type="submit">Desvincular</button></form></td></tr><?php }?></tbody></table></div><?php }?></section><?php }prog_footer(); ?>